  ($t$LEI-7347-1985|corpo|art. 15$t$, $t$Decorridos 60 (sessenta) dias do trânsito em julgado da sentença condenatória, sem que a associação autora lhe promova a execução, deverá fazê-lo o Ministério Público.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1985-07-25$t$, $t$1990-09-11$t$, $t$2026-10-20$t$, $t$17e8ac902e71b524ff6059574eae56f3eae0c6b44ae902aeda5bdcd7b141ea1b$t$, null, null),
  ($t$LEI-7347-1985|corpo|art. 1º, V$t$, $t$por infração da ordem econômica e da economia popular;$t$, $t$redacao_dada$t$, $t$medida-provisoria:2180:2001$t$, null, null, null, 2001, $t$ano$t$, null, $t$2011-11-30$t$, $t$2026-10-20$t$, $t$bafae3e43c13b100b206a7095175641b682633e9b2cf9bd886ea36e4ceb66b7f$t$, null, null),
  ($t$LEI-8069-1990|corpo|art. 4º$t$, $t$É dever da família, da comunidade, da sociedade em geral e do poder público assegurar, com absoluta prioridade, a efetivação dos direitos referentes à vida, à saúde, à alimentação, à educação, ao esporte, ao lazer, à profissionalização, à cultura, à dignidade, ao respeito, à liberdade e à convivência familiar e comunitária.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-07-16$t$, $t$2026-09-22$t$, $t$2026-10-20$t$, $t$4f3e14455757ce7b948150a8c3a730b90a4d0b13bfe42abc351707f2136dd317$t$, null, null),
  ($t$LEI-8069-1990|corpo|art. 87, II$t$, $t$políticas e programas de assistência social, em caráter supletivo, para aqueles que deles necessitem$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-07-16$t$, $t$2016-03-08$t$, $t$2026-10-20$t$, $t$e680171d3b75a18033a9aed755e65546a70d1eeb94cbac9fde89e28f244ac964$t$, null, null),
  ($t$LEI-8078-1990|corpo|art. 4º$t$, $t$A Política Nacional de Relações de Consumo tem por objetivo o atendimento das necessidades dos consumidores, o respeito a sua dignidade, saúde e segurança, a proteção de seus interesses econômicos, a melhoria da sua qualidade de vida, bem como a transferência e harmonia das relações de consumo, atendidos os seguintes princípios:$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-09-12$t$, $t$1995-03-21$t$, $t$2026-10-20$t$, $t$eb3365c565ea891f22da60358038961acddfa43ae555a08d0b629fdcb5fa82d9$t$, null, null),
  ($t$LEI-8078-1990|corpo|art. 57$t$, $t$A pena de multa, graduada de acordo com a gravidade da infração, a vantagem auferida e a condição econômica do fornecedor será aplicada mediante procedimento administrativo nos termos da lei, revertendo para o fundo de que trata a Lei n° 7.347, de 24 de julho de 1985, sendo a infração ou dano de âmbito nacional, ou para os fundos estaduais de proteção ao consumidor nos demais casos.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-09-12$t$, $t$1993-05-21$t$, $t$2026-10-20$t$, $t$206c695143fe260632ad2156ff8f8aa19e006c14473066d23b6b2c3e156136c9$t$, null, null),
  ($t$LEI-8112-1990|corpo|art. 247$t$, $t$Para efeito do disposto no § 2° do art. 231, haverá ajuste de contas com a Previdência Social, correspondente ao período de contribuição por parte dos servidores celetistas abrangidos pelo art. 243.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-12-12$t$, $t$1991-01-08$t$, $t$2026-10-19$t$, $t$646ab31efbb73c2f7ae89b89ad4d5acda68120b85bf9d82f00213f20739f09c9$t$, null, null),
  ($t$LEI-8112-1990|corpo|art. 9º, II$t$, $t$em comissão, para cargos de confiança, de livre exoneração.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1990-12-12$t$, $t$1997-12-10$t$, $t$2026-10-19$t$, $t$1f674a10b2b3dc767548de9134c4caa2fb1e6d489aae08da238c9964f9a4853a$t$, null, null),
  ($t$LEI-8213-1991|corpo|art. 151$t$, $t$Até que seja elaborada a lista de doenças mencionadas no inciso II do art. 26, independe de carência a concessão de auxílio-doença e aposentadoria por invalidez ao segurado que, após filiar-se ao Regime Geral de Previdência Social, for acometido das seguintes doenças: tuberculose ativa; hanseníase; alienação mental; neoplasia maligna; cegueira; paralisia irreversível e incapacitante; cardiopatia grave; doença de Parkinson; espondiloartrose anquilosante; nefropatia grave; estado avançado da doença de Paget (osteíte deformante); síndrome da deficiência imunológica adquirida-Aids; e contaminação por radiação, com base em conclusão da medicina especializada.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-07-25$t$, $t$2015-06-17$t$, $t$2026-10-19$t$, $t$efb5b25412761739c05b085dd43930b3edf90cbbde8d9f2798be15e61f32d878$t$, null, null),
  ($t$LEI-8213-1991|corpo|art. 29, § 3º$t$, $t$Serão considerados para o cálculo do salário-de-benefício os ganhos habituais do segurado empregado, a qualquer título, sob forma de moeda corrente ou de utilidades, sobre os quais tenha incidido contribuição previdenciária.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-07-25$t$, $t$1994-04-15$t$, $t$2026-10-19$t$, $t$e9b6cee48fafb9d9ff6b5725bd6584066141abb6d97f91ae7033cd6dfc454849$t$, null, null),
  ($t$LEI-8213-1991|corpo|art. 44$t$, $t$A aposentadoria por invalidez, observado o disposto na Seção III deste capítulo, especialmente no art. 33, consistirá numa renda mensal correspondente a:$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-07-25$t$, $t$1995-04-28$t$, $t$2026-10-19$t$, $t$32945dca080751130b51af11594470890f0aa2bbb4b8e2620dd8460a74618690$t$, null, null),
  ($t$LEI-8213-1991|corpo|art. 6º$t$, $t$O Conselho Nacional de Previdência Social (CNPS) deverá indicar cidadão de notório conhecimento na área para exercer a função de Ouvidor Geral da Previdência Social, que terá mandato de 2 (dois) anos, sendo vedada a sua recondução.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-07-25$t$, $t$1998-11-20$t$, $t$2026-10-19$t$, $t$62fc0851115c9b78d70d9963da3a3c247db4f046f40e121f54d3bba89fda0ca6$t$, null, null),
  ($t$LEI-8213-1991|corpo|art. 72$t$, $t$O salário-maternidade para a segurada empregada ou trabalhadora avulsa consistirá numa renda mensal igual à sua remuneração integral e será pago pela empresa, efetivando-se a compensação quando do recolhimento das contribuições, sobre a folha de salários.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-07-25$t$, $t$1999-11-28$t$, $t$2026-10-19$t$, $t$7114431d1bec6df42b72f0a2f8a30c0dfcd9f104dda0813b295fcd1c9349fdfe$t$, null, null),
  ($t$LEI-8245-1991|corpo|art. 12$t$, $t$Em casos de separação de fato, separação judicial, divórcio ou dissolução da sociedade concubinária, a locação prosseguirá automaticamente com o cônjuge ou companheiro que permanecer no imóvel.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1991-10-21$t$, $t$2009-12-09$t$, $t$2026-10-20$t$, $t$84658b09ab5049a25afaa13e1a9c8b6da49a5ba1d1760e7cc092a932af1407a3$t$, null, null),
  ($t$LEI-8429-1992|corpo|art. 1º$t$, $t$Os atos de improbidade praticados por qualquer agente público, servidor ou não, contra a administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios, de Território, de empresa incorporada ao patrimônio público ou de entidade para cuja criação ou custeio o erário haja concorrido ou concorra com mais de cinqüenta por cento do patrimônio ou da receita anual, serão punidos na forma desta lei.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1992-06-03$t$, $t$2021-10-25$t$, $t$2026-10-20$t$, $t$b0c9f1ef81353395f79b86d6b86f0b5f60870abf537b47aa96ba72be6391c32e$t$, null, null),
  ($t$LEI-9099-1995|corpo|art. 23$t$, $t$Não comparecendo o demandado, o Juiz togado proferirá sentença.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1995-09-27$t$, $t$2020-04-26$t$, $t$2026-10-19$t$, $t$fd98807c85743e952e0eb7019e487fb2c527a2d8182d650f1475cf43527881e2$t$, null, null),
  ($t$LEI-9099-1995|corpo|art. 60$t$, $t$O Juizado Especial Criminal, provido por Juízes togados ou togados e leigos, tem competência para a conciliação, o julgamento e a execução das infrações penais de menor potencial ofensivo.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1995-09-27$t$, $t$2006-06-28$t$, $t$2026-10-19$t$, $t$5e5c6a4b43c4f06d15fcc4074ec07ec3d1e4cad33ed89e96e2e1eea74a8064ca$t$, null, null),
  ($t$LEI-9099-1995|corpo|art. 69, parágrafo único$t$, $t$Ao autor do fato que, após a lavratura do termo, for imediatamente encaminhado ao Juizado ou assumir o compromisso de a ele comparecer, não se imporá prisão em flagrante, nem se exigirá fiança.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1995-09-27$t$, $t$2002-05-13$t$, $t$2026-10-19$t$, $t$99368d63f21a049eb1ec787d39b3b410d414d4cc23dcba3b9e0bf8aeb511022b$t$, null, null),
  ($t$LEI-9099-1995|corpo|art. 83, § 2º$t$, $t$Quando opostos contra sentença, os embargos de declaração suspenderão o prazo para o recurso.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1995-09-27$t$, $t$2015-03-16$t$, $t$2026-10-19$t$, $t$48e7621fe089ac7ef1dbea425c7d5bc1cc9860cc59cbabc86dc470df02ba5aa9$t$, null, null),
  ($t$LEI-9099-1995|corpo|art. 8º, § 1º$t$, $t$Somente as pessoas físicas capazes serão admitidas a propor ação perante o Juizado Especial, excluídos os cessionários de direito de pessoas jurídicas.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1995-09-27$t$, $t$2009-12-16$t$, $t$2026-10-19$t$, $t$73ee4e3c3b7a7e96a15f2f616db687674d8f70e9eea562c360893366b583d155$t$, null, null),
  ($t$LEI-9307-1996|corpo|art. 13, § 4º$t$, $t$Sendo nomeados vários árbitros, estes, por maioria, elegerão o presidente do tribunal arbitral. Não havendo consenso, será designado presidente o mais idoso.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1996-09-24$t$, $t$2015-05-26$t$, $t$2026-10-19$t$, $t$cdb7bd935e86bcaca27ac512123e9927e0331aa10075bdca3ec3e83dbf02902c$t$, null, null),
  ($t$LEI-9503-1997|corpo|art. 174$t$, $t$Promover, na via, competição esportiva, eventos organizados, exibição e demonstração de perícia em manobra de veículo, ou deles participar, como condutor, sem permissão da autoridade de trânsito com circunscrição sobre a via:$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1997-09-24$t$, $t$2014-05-11$t$, $t$2026-10-20$t$, $t$3ebe62a660b771af0461461cfb84bbcc8256cb2b704fa71bfe840f6a157fc876$t$, null, null),
  ($t$LEI-9503-1997|corpo|art. 2º, parágrafo único$t$, $t$Para os efeitos deste Código, são consideradas vias terrestres as praias abertas à circulação pública e as vias internas pertencentes aos condomínios constituídos por unidades autônomas.$t$, $t$redacao_original$t$, null, null, null, null, null, $t$norma$t$, $t$1997-09-24$t$, $t$2015-07-06$t$, $t$2026-10-20$t$, $t$c68f8341f39e9fcacc8ce9457fc88ada9c745293d89fb326bf5420a893fe2920$t$, null, null)
),
inseridas as (
  insert into public.versoes_dispositivo
    (dispositivo_id, texto, origem, ato_chave, ato_rotulo, ato_assinatura, ato_publicacao, ano_do_ato, fonte_da_data, vigente_de, vigente_ate,
     vigencia_confirmada, texto_anterior_disponivel, conhecido_em, hash, fonte_do_texto, conferida_por, conferida_em)
  select n.dispositivo_id, n.texto, n.origem, n.ato_chave, n.ato_rotulo, n.ato_assinatura::date, n.ato_publicacao::date, n.ano_do_ato::integer, n.fonte_da_data,
         n.vigente_de::date, n.vigente_ate::date, false, false, n.conhecido_em::date, n.hash, 'tachado_planalto', n.conferida_por, n.conferida_em::date
  from novas n
  where exists (select 1 from public.dispositivos d where d.id = n.dispositivo_id)
    and not exists (select 1 from public.versoes_dispositivo x where x.dispositivo_id = n.dispositivo_id and x.vigente_ate is not null)
  returning dispositivo_id
)
update public.versoes_dispositivo v set texto_anterior_disponivel = true
where v.vigente_ate is null and v.dispositivo_id in (select dispositivo_id from novas);

commit;

select
  (select count(*) from public.versoes_dispositivo where fonte_do_texto = 'tachado_planalto') as redacoes_anteriores,
  (select count(*) from public.versoes_dispositivo v where v.vigente_ate is null and v.texto_anterior_disponivel and exists (select 1 from public.versoes_dispositivo x where x.dispositivo_id = v.dispositivo_id and x.fonte_do_texto = 'tachado_planalto')) as vigentes_marcadas;
